var xrandseed = []; // generates the random seed
var yrandseed = [];
var xlines = []; // 2d box edge info to calculate exits
var ylines = []; // 2d
var boxexit = []; // 2d box exits info: 1 for up, 2 right, 4 down, 8 left
var boxocc = []; // 2d boxes occupied? has 0 or 1
var queuex = [];
var queuey = [];
var colsx, rowsy;
var cellsize = 10;
var f; // colour variable

function setup() {
  createCanvas(1000, 700);
  colorMode(RGB);
  background(255);
	strokeWeight(1.5);
  colsx = 98; // how many columns
  rowsy = 62; // how many rows
  for (let r = 0; r < rowsy; r++) {
    xlines[r] = [];
    for (let c = 0; c < colsx - 1; c++) {
      xlines[r][c] = 0;
    }
  }
  for (let c = 0; c < colsx; c++) {
    ylines[c] = [];
    for (let r = 0; r < rowsy - 1; r++) {
      ylines[c][r] = 0;
    }
  }
  for (let r = 0; r < rowsy - 1; r++) {
    boxexit[r] = [];
    boxocc[r] = [];
    for (let c = 0; c < colsx - 1; c++) {
      boxexit[r][c] = 0;
      boxocc[r][c] = 0;
    }
  }
  f = color(255, 255, 245);
  generate();
  boxvalues();
  drawlines();
  screenoptions();
  palette();
}

function draw() {
}

function drawlines() {
  for (let count = 0; count < rowsy; count++) {
    if (yrandseed[count] == 1) {
      for (let i = 1; i < colsx; i += 2) {
        line(i * cellsize, (count + 1) * cellsize, i * cellsize + cellsize, (count + 1) * cellsize);
      }
    } else {
      for (let i = 2; i < colsx; i += 2) {
        line(i * cellsize, (count + 1) * cellsize, i * cellsize + cellsize, (count + 1) * cellsize);
      }
    }
    for (let i = 1; i < colsx; i++) { // fill edges so no gaps
      line(i * cellsize, cellsize, i * cellsize + cellsize, cellsize);
      line(i * cellsize, rowsy * cellsize, i * cellsize + cellsize, rowsy * cellsize);
    }
  }

  for (let count = 0; count < colsx; count++) {
    if (xrandseed[count] == 1) {
      for (let i = 1; i < rowsy; i += 2) {
        line((count + 1) * cellsize, i * cellsize, (count + 1) * cellsize, i * cellsize + cellsize);
      }
    } else {
      for (let i = 2; i < rowsy; i += 2) {
        line((count + 1) * cellsize, i * cellsize, (count + 1) * cellsize, i * cellsize + cellsize);
      }
    }
    for (let i = 1; i < rowsy; i++) { // fill edges so no gaps
      line(cellsize, i * cellsize, cellsize, i * cellsize + cellsize);
      line(colsx * cellsize, i * cellsize, colsx * cellsize, i * cellsize + cellsize);
    }
  }
}

function generate() { // generates the random seed and populates lines arrays
  for (let i = 0; i < int(colsx / 2) + 1; i++) {
    xrandseed[i] = int(random(2));
    xrandseed[colsx - i - 1] = xrandseed[i];
  }
  for (let i = 0; i < int(rowsy / 2) + 1; i++) {
    yrandseed[i] = xrandseed[i];
    yrandseed[rowsy - i - 1] = xrandseed[i];
  }

  //         ************  populate line arrays for box edges

  for (let count = 0; count < rowsy; count++) { // all x's along each row
    if (yrandseed[count] == 0) {
      for (let i = 0; i < colsx - 1; i++) {
        xlines[count][i] = i % 2;
      }
    } else {
      for (let i = 0; i < colsx - 1; i++) {
        xlines[count][i] = (i + 1) % 2;
      }
    }
    for (let i = 0; i < colsx - 1; i++) { // fill edges so no gaps
      xlines[0][i] = 1;
      xlines[rowsy - 1][i] = 1;
    }
  }

  for (let count = 0; count < colsx; count++) { // all y's down each column
    if (xrandseed[count] == 0) {
      for (let i = 0; i < rowsy - 1; i++) {
        ylines[count][i] = i % 2;
      }
    } else {
      for (let i = 0; i < rowsy - 1; i++) {
        ylines[count][i] = (i + 1) % 2;
      }
    }
    for (let i = 0; i < rowsy - 1; i++) { // fill edges so no gaps
      ylines[0][i] = 1;
      ylines[colsx - 1][i] = 1;
    }
  }
}

function boxvalues() { // calculate how many edges box has

  for (let y = 0; y < rowsy - 1; y++) { // zero all boxes
    for (let x = 0; x < colsx - 1; x++) {
      boxexit[y][x] = 0;
    }
  }

  for (let y = 0; y < rowsy - 1; y++) { // calculate all boxes
    for (let x = 0; x < colsx - 1; x++) {
      if (xlines[y][x] == 1) {
        boxexit[y][x] += 1;
      }
      if (xlines[y + 1][x] == 1) {
        boxexit[y][x] += 4;
      }
      if (ylines[x][y] == 1) {
        boxexit[y][x] += 8;
      }
      if (ylines[x + 1][y] == 1) {
        boxexit[y][x] += 2;
      }
    }
  }
}

function fillbox(y, x) {
  boxocc[y][x] = 1; // mark box as filled
  fill(f);
  noStroke();
  square(x * cellsize + cellsize, y * cellsize + cellsize, 10);

  if (boxexit[y][x] != 15) { // only continue if open neighbours
    let sides = boxexit[y][x];
    switch (sides) {
      case 0:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 1:
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 2:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 3:
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 4:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 5:
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 6:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 7:
        if (boxocc[y][x - 1] == 0) { // left
          queuey = append(queuey, y);
          queuex = append(queuex, x - 1);
        }
        break;
      case 8:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        break;
      case 9:
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        break;
      case 10:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        break;
      case 11:
        if (boxocc[y + 1][x] == 0) { // down
          queuey = append(queuey, y + 1);
          queuex = append(queuex, x);
        }
        break;
      case 12:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        break;
      case 13:
        if (boxocc[y][x + 1] == 0) { // right
          queuey = append(queuey, y);
          queuex = append(queuex, x + 1);
        }
        break;
      case 14:
        if (boxocc[y - 1][x] == 0) { // up
          queuey = append(queuey, y - 1);
          queuex = append(queuex, x);
        }
        break;
    }
  }
  let temp = queuex.length;
  if (temp > 0) {
    let tempx = queuex[temp - 1];
    let tempy = queuey[temp - 1];
    queuex = shorten(queuex);
    queuey = shorten(queuey);
    fillbox(tempy, tempx);
  }
  for (let i = 0; i < rowsy - 1; i++) {
    for (let j = 0; j < colsx - 1; j++) {
      boxocc[i][j] = 0;
    }
  }
}

